const monthlyBooking=(bookings:Row[],employeeId:string,year:number,month:number)=>{const first=new Date(Date.UTC(year,month,1)),last=new Date(Date.UTC(year,month+1,0));const weekdays=(a:Date,b:Date)=>{let n=0;for(let d=new Date(a);d<=b;d.setUTCDate(d.getUTCDate()+1))if(d.getUTCDay()!==0&&d.getUTCDay()!==6)n++;return n};const days=weekdays(first,last);let allocated=0,billable=0;let invalid=false;let hasBooking=false;for(const b of bookings.filter(x=>x.employeeId===employeeId)){const validDate=(s:string)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T00:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===s};const start=b.start||'',end=b.end||start,raw=Number(b.allocation);if(!validDate(start)||!validDate(end)||!Number.isFinite(raw)||b.allocation===''||raw<0||raw>100){invalid=true;continue}const a=new Date(start+'T00:00:00Z'),z=new Date(end+'T00:00:00Z');if(z<a){invalid=true;continue}const lo=a>first?a:first,hi=z<last?z:last;if(hi<lo)continue;hasBooking=true;const percent=weekdays(lo,hi)*raw/(days||1);allocated+=percent;if(b.utilize!=='false')billable+=percent}return {allocation:allocated,billable,invalid,hasBooking}};
const bookingOverlaps=(bookings:Row[],employeeId:string,year:number,month:number)=>{const start=new Date(Date.UTC(year,month,1)),end=new Date(Date.UTC(year,month+1,0));const items=bookings.filter(b=>b.employeeId===employeeId).map(b=>({row:b,from:new Date((b.start||'')+'T00:00:00Z'),to:new Date((b.end||b.start||'')+'T00:00:00Z')})).filter(b=>Number.isFinite(b.from.getTime())&&Number.isFinite(b.to.getTime())&&b.from<=b.to&&b.from<=end&&b.to>=start);const pairs:Array<{first:Row;second:Row}>=[];for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){const a=items[i],b=items[j];const lo=new Date(Math.max(a.from.getTime(),b.from.getTime(),start.getTime())),hi=new Date(Math.min(a.to.getTime(),b.to.getTime(),end.getTime()));if(lo<=hi){let workday=false;for(let d=new Date(lo);d<=hi;d.setUTCDate(d.getUTCDate()+1))if(d.getUTCDay()!==0&&d.getUTCDay()!==6){workday=true;break}if(workday)pairs.push({first:a.row,second:b.row})}}return pairs};
const bookingStatus=(a:number,b:number)=>a>100.00001?'overbooked':a<99.99999?'underallocated':b<99.99999?'nonbillable':'billable';
