let token='';
const tokenStorageKey='empeval-google-session';
const restoreToken=()=>{try{const stored=JSON.parse(sessionStorage.getItem(tokenStorageKey)||'null') as {token:string;expiresAt:number}|null;if(stored?.token&&stored.expiresAt>Date.now()+60000){token=stored.token;return true}}catch{}sessionStorage.removeItem(tokenStorageKey);return false};

let googleScriptPromise:Promise<void>|null=null;
function prepareGoogle(){if(window.google)return Promise.resolve();if(!googleScriptPromise)googleScriptPromise=new Promise<void>((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>resolve();script.onerror=()=>{googleScriptPromise=null;reject(Error('Unable to load Google sign-in. Check Safari content blockers or network settings.'))};document.head.append(script)});return googleScriptPromise}
function signIn(){if(!clientId)return Promise.reject(Error('Missing Google OAuth client ID'));if(!window.google)return Promise.reject(Error('Google sign-in is not ready. Please try again.'));return new Promise<void>((resolve,reject)=>{try{window.google!.accounts.oauth2.initTokenClient({client_id:clientId!,scope:'https://www.googleapis.com/auth/spreadsheets',callback:r=>r.access_token?(token=r.access_token,sessionStorage.setItem(tokenStorageKey,JSON.stringify({token,expiresAt:Date.now()+(('expires_in' in r&&typeof r.expires_in==='number')?r.expires_in:3600)*1000})),resolve()):reject(Error(r.error||'Google sign-in cancelled or failed'))}).requestAccessToken({prompt:'select_account'})}catch(e){reject(e)}})}
async function transport(path:string,method='GET',body?:unknown){if(!token||!spreadsheet)throw Error('Connect Google first');const response=await fetch('https://sheets.googleapis.com/v4/spreadsheets/'+spreadsheet+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(response.status===401){token='';sessionStorage.removeItem(tokenStorageKey)}if(!response.ok)throw Error('Google Sheets '+response.status+': '+(await response.text()).slice(0,300));return response.json()}
