const trackedTransport=async(path:string,method?:string,body?:unknown)=>{const result=await transport(path,method,body);const p=progressRef.current;if(p){const next={...p,done:Math.min(p.total,p.done+1)};progressRef.current=next;setProgress(next)}return result};
